package parsing

import "testing"

func TestGeneratedHeader(t *testing.T) {
	for src, want := range map[string]bool{
		"// Code generated by protoc-gen-go. DO NOT EDIT.\npackage a\n":                                                     true,
		"// @generated\nfn f() {}\n":                                                                                        true,
		"// <auto-generated>\n//     This code was generated by a tool.\n":                                                  true,
		"// GENERATED CODE - DO NOT MODIFY BY HAND\npart of 'a.dart';\n":                                                    true,
		"# Generated by Django 4.2 on 2024-01-01\nfrom django.db import x\n":                                                true,
		"/* This file was automatically generated. */\n":                                                                    true,
		"\"\"\"\nDjango settings for blog project.\n\nGenerated by 'django-admin startproject' using Django 5.0.\n\"\"\"\n": false,
		"\"\"\"\nURL configuration for blog project.\n\nGenerated by 'django-admin startproject'.\n\"\"\"\n":                false,
		"// Rebuilds the regenerated cache on start.\nfunc f() {}\n":                                                        false,
		"// Ungenerated fixtures live in testdata.\n":                                                                       false,
		"package a\n\nfunc f() {}\n":                                                                                        false,
	} {
		if got := GeneratedHeader([]byte(src)); got != want {
			t.Errorf("GeneratedHeader(%q) = %v, want %v", src, got, want)
		}
	}
}
